export let Modal = Object.assign(
  ({
    title,
    description,
    isOpen,
    onClose,
    children
  }: {
    title: string;
    description: string;
    isOpen: boolean;
    onClose: () => void;
    children: React.ReactNode;
  }) => {
    let openDelayed = useDelayed(isOpen, 300, [true]);
    let showBlanket = useDelayed(isOpen, 100, [false]);

    return (
      <Dialog.Root open={openDelayed} onOpenChange={onClose}>
        <Dialog.Portal>
          <Blanket style={{ opacity: showBlanket ? 1 : 0 }} />

          <Dialog.Content>
            <AnimatePresence>
              {isOpen && (
                <motion.div
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -30 }}
                  style={{ position: 'fixed', top: '50%', left: '50%', zIndex: 1001 }}
                  transition={{ duration: 0.3, ease: 'easeInOut' }}
                >
                  <Content>
                    <Header>
                      <div>
                        <Title>{title}</Title>
                        <Description>{description}</Description>
                      </div>

                      <Dialog.Close asChild>
                        <FloatingClose aria-label="Close">
                          <X />
                        </FloatingClose>
                      </Dialog.Close>
                    </Header>

                    <main>{children}</main>
                  </Content>
                </motion.div>
              )}
            </AnimatePresence>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    );
  },
  {
    Actions: styled.div`
      display: flex;
      gap: 10px;
      justify-content: flex-end;
      margin-top: 20px;
    `
  }
);

